from __future__ import annotations

from enum import StrEnum
from functools import cache
from typing import Self

import polars as pl
from pydantic import BaseModel

from ds.data.char_icons import (
    CHAR_GROUP_NAMES,
    CHAR_GROUPS,
    char_group_by_name,
    char_icon,
    char_id_by_name,
)
from ds.data.paths import PARQUET_DIR

__all__ = ["CharChoice", "CharEnum", "CharGroup", "CharId"]

_CHAR_PARQUET = PARQUET_DIR / "char.parquet"


class CharChoice(BaseModel):
    """One character as a picker shows it"""

    value: str
    label: str
    icon: str  # path under pkgs/ds/data/, eg 'char_icons/little_mac.png'


# ds::exception: caching (approved 2026-11-15): names from char.parquet, which only changes on
#   a roster re-scrape (new DLC)
@cache
def _names() -> dict[str, str]:
    """Display name of every fighter id and every group id"""
    chars = pl.read_parquet(_CHAR_PARQUET)
    return dict(chars.select("id", "name").iter_rows()) | CHAR_GROUP_NAMES


class CharEnum(StrEnum):
    """Base of the character enums: lenient parsing, display name and icon.

    `Cls(text)` accepts the id, the display name as any site writes it ('Mr. Game & Watch',
    'Banjo-Kazooie') and a partial name that fits exactly one member ('mac'). pydantic uses
    the same rule, so a tool argument of this type takes what the model or a person writes.
    A plain `ValueError` for anything else.
    """

    @classmethod
    def _missing_(cls, value: object) -> Self | None:
        text = str(value).strip()
        for found in (char_group_by_name(text), char_id_by_name(text)):
            if found in cls._value2member_map_:
                return cls(found)
        wanted = text.lower()
        partial = [m for m in cls if wanted and (wanted in m.label.lower() or wanted.replace(" ", "_") in m.value)]
        return partial[0] if len(partial) == 1 else None

    @property
    def label(self) -> str:
        """Display name, eg 'Little Mac', 'Pokemon Trainer'"""
        return _names().get(self.value, self.value)

    @property
    def icon(self) -> str:
        """Stock icon path under pkgs/ds/data/, eg 'char_icons/little_mac.png'"""
        return char_icon(CHAR_GROUPS.get(self.value, (self.value,))[0])

    @classmethod
    def choices(cls) -> list[CharChoice]:
        """Every member for a picker, sorted by display name"""
        members = sorted(cls, key=lambda m: m.label.lower())
        return [CharChoice(value=m.value, label=m.label, icon=m.icon) for m in members]


